from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            comps.append((color, cells))

    # The instruction is the unique large, two-armed L made from one color.
    markers = []
    for i, (color, cells) in enumerate(comps):
        if color == bg or len(cells) < 5:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        # Find the corner where a full vertical and a full horizontal arm meet.
        for br in (r0, r1):
            for bc in (c0, c1):
                vertical = {(r, bc) for r in range(r0, r1 + 1)}
                horizontal = {(br, c) for c in range(c0, c1 + 1)}
                if cells == vertical | horizontal and len(vertical) >= 3 and len(horizontal) >= 3:
                    dr = 1 if br == r0 else -1
                    dc = 1 if bc == c0 else -1
                    markers.append((i, color, br, bc, dr, dc))
    if not markers:
        return [row[:] for row in grid]
    mi, marker_color, br, bc, dr, dc = max(markers, key=lambda x: len(comps[x[0]][1]))

    # Find repeated same-color shapes; recolor the copy in the L's outward quadrant.
    groups = defaultdict(list)
    for i, (color, cells) in enumerate(comps):
        if i == mi or color == bg or color == marker_color:
            continue
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        shape = frozenset((r - r0, c - c0) for r, c in cells)
        groups[(color, shape)].append((i, cells))

    candidates = []
    for (color, shape), copies in groups.items():
        if len(copies) < 2:
            continue
        for i, cells in copies:
            # Inclusive on the arm axis, since an object may lie directly in line with it.
            rs = [r for r, c in cells]
            cs = [c for r, c in cells]
            rside = min(rs) >= br if dr > 0 else max(rs) <= br
            cside = min(cs) >= bc if dc > 0 else max(cs) <= bc
            if rside and cside:
                # Prefer the target closest to the corner if several repeated motifs qualify.
                dist = min(abs(r - br) + abs(c - bc) for r, c in cells)
                candidates.append((dist, i, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = min(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = marker_color
    return out


